18	namespace llm {
19	namespace {
20	constexpr size_t kSrcAndDstNum = 2U;
21	
22	ge::Status SetBufferInfoCount(const PullCacheParam &pull_cache_param, uint32_t &buffer_info_count,
23	                              uint32_t &is_pull_block,
24	                              std::vector<std::vector<std::pair<int64_t, int64_t>>> &contiguous_blocks_pair) {
25	  LLM_CHK_BOOL_RET_STATUS(pull_cache_param.prompt_blocks.empty() || !pull_cache_param.decoder_blocks.empty(),
26	                          ge::LLM_PARAM_INVALID, "Pulling from discrete memory to continuous memory is not supported");
27	  if (pull_cache_param.decoder_blocks.empty()) {
28	    buffer_info_count = 1U;
29	    LLMLOGD("enter pull from contiguous to contiguous");
30	  } else if (pull_cache_param.prompt_blocks.empty()) {
31	    for (size_t i = 0UL; i < pull_cache_param.decoder_blocks.size(); ++i) {
32	      std::vector<std::pair<int64_t, int64_t>> block_pair{std::make_pair(i, pull_cache_param.decoder_blocks[i])};
33	      contiguous_blocks_pair.emplace_back(std::move(block_pair));
34	      buffer_info_count = contiguous_blocks_pair.size();
35	    }
36	    LLMLOGD("enter pull from contiguous to discrete");
37	  } else {
38	    is_pull_block = 1;
39	    LLM_CHK_STATUS_RET(LLMUtils::FindContiguousBlockIndexPair(pull_cache_param.prompt_blocks,
40	                                                              pull_cache_param.decoder_blocks, contiguous_blocks_pair),
41	                       "find contiguous blocks failed");
42	    buffer_info_count = contiguous_blocks_pair.size();
43	    LLMLOGD("enter pull from discrete to discrete");
44	  }
45	
46	  LLMLOGD("request set buffer info count is:%u", buffer_info_count);
47	  return ge::SUCCESS;
48	}
49	
50	void SetDstAddr(const PullCacheParam &pull_cache_param, const CacheEntry &cache_entry, TransferCacheReq &request) {
51	  request.block_size = 0U;
52	  uint64_t layer_start_tensor_index = 0U;
53	  if (!pull_cache_param.dst_tensor_indices.empty()) {
54	    layer_start_tensor_index = pull_cache_param.dst_tensor_indices.front();
55	  }
56	  for (size_t i = 0UL; i < request.dst_addr_count; ++i) {
57	    if (pull_cache_param.decoder_blocks.empty()) {
58	      request.transfer_infos[i].dst_addr =
59	          ValueToPtr(PtrToValue(cache_entry.cache_addrs[i + layer_start_tensor_index].get()) +
60	                     pull_cache_param.batch_index * cache_entry.stride);
61	      LLMLOGD("request set %zuth dst_addr:%lu", i, reinterpret_cast<uintptr_t>(request.transfer_infos[i].dst_addr));
62	    } else {
63	      request.block_size = cache_entry.stride;
64	      request.transfer_infos[i].dst_addr = cache_entry.cache_addrs[i + layer_start_tensor_index].get();
65	      LLMLOGD("request set block size is:%lu, set %zuth dst_addr:%lu", cache_entry.stride, i,
66	              reinterpret_cast<uintptr_t>(request.transfer_infos[i].dst_addr));
67	    }
68	  }
69	}
70	
71	ge::Status SetBufferInfo(const PullCacheParam &pull_cache_param, const CacheEntry &cache_entry,
72	                         const std::vector<std::vector<std::pair<int64_t, int64_t>>> &contiguous_blocks_pair,
73	                         TransferCacheReq &request) {
74	  const uint32_t dst_addr_count = request.dst_addr_count;
75	  const uint64_t pull_size = request.pull_size;
76	  for (uint32_t i = 0U; i < request.buffer_info_count; ++i) {
77	    auto &src_buffer_info = request.transfer_infos[dst_addr_count + i].buffer_info;
78	    auto &dst_buffer_info = request.transfer_infos[dst_addr_count + request.buffer_info_count + i].buffer_info;
79	    if (pull_cache_param.decoder_blocks.empty()) {
80	      dst_buffer_info.buffer_len = pull_size;
81	      dst_buffer_info.block_start_index = 0U;
82	      src_buffer_info.buffer_len = pull_size;
83	      src_buffer_info.block_start_index = 0U;
84	      LLMLOGD("request buffer_len is:%lu, block_start_index is:%lu", dst_buffer_info.buffer_len,
85	              dst_buffer_info.block_start_index);
86	      break;
87	    }
88	    const auto &contiguous_block_pair = contiguous_blocks_pair[i];
89	    const int64_t dst_index = contiguous_block_pair.front().second;
90	    const int64_t dst_end_index = contiguous_block_pair.back().second;
91	    LLM_CHK_BOOL_RET_STATUS((static_cast<uint64_t>(dst_index) < cache_entry.num_blocks) &&
92	                                (static_cast<uint64_t>(dst_end_index) < cache_entry.num_blocks),
93	                            ge::LLM_PARAM_INVALID,
94	                            "dst block begin index[%ld] or dst block end index[%ld] is out of range[0, %lu)", dst_index,
95	                            dst_end_index, cache_entry.num_blocks);
96	    src_buffer_info.buffer_len = contiguous_block_pair.size() * cache_entry.stride;
97	    src_buffer_info.block_start_index = contiguous_blocks_pair[i].front().first;
98	    dst_buffer_info.buffer_len = contiguous_block_pair.size() * cache_entry.stride;
99	    dst_buffer_info.block_start_index = contiguous_blocks_pair[i].front().second;
100	    LLMLOGD("request buffer_len is:%lu, src block start index is:%lu, dst block start index is:%lu",
101	            src_buffer_info.buffer_len, src_buffer_info.block_start_index, dst_buffer_info.block_start_index);
102	  }
103	  return ge::SUCCESS;
104	}
105	
106	}  // namespace
107	
108	ge::Status DataTransferClient::ConstructTransferInfo(const PullCacheParam &pull_cache_param,
109	                                                     const CacheEntry &cache_entry, const CacheKey &cache_key,
110	                                                     int32_t timeout) const {
111	  std::vector<std::vector<std::pair<int64_t, int64_t>>> contiguous_blocks_pair;
112	  uint32_t buffer_info_count = 0U;
113	  uint32_t is_pull_block = 0U;
114	  LLM_CHK_STATUS_RET(SetBufferInfoCount(pull_cache_param, buffer_info_count, is_pull_block, contiguous_blocks_pair),
115	                     "set buffer_info_count failed");
116	  const uint32_t dst_addr_count = pull_cache_param.dst_tensor_indices.empty()
117	                                      ? static_cast<uint32_t>(cache_entry.cache_addrs.size())
118	                                      : static_cast<uint32_t>(pull_cache_param.dst_tensor_indices.size());
119	  const uint64_t request_size = transfer_message_limits::CalcMinRequestSize(dst_addr_count, buffer_info_count,
120	                                                                            static_cast<uint32_t>(kSrcAndDstNum));
121	  TransferCacheReq *request_ptr = nullptr;
122	  LLM_CHK_STATUS_RET(comm_entity_->GetTransferCacheReq(request_size, request_ptr), "Failed to get transfer cache req");
123	  LLM_ASSERT_NOTNULL(request_ptr);
124	  TransferCacheReq &request = *request_ptr;
125	  request.cache_id = cache_key.prompt_cache_id;
126	  request.batch_index = cache_key.prompt_batch_index;
127	  request.req_id = cache_key.req_id;
128	  request.prefix_id = cache_key.prefix_id;
129	  request.model_id = cache_key.model_id;
130	  request.dst_addr_count = dst_addr_count;
131	  request.buffer_info_count = buffer_info_count;
132	  request.is_pull_block = is_pull_block;
133	  request.dst_placement = 1;
134	  request.timeout_in_ms = timeout;
135	  request.num_tensors = request.dst_addr_count;
136	  request.pull_size = pull_cache_param.size > 0 ? static_cast<uint64_t>(pull_cache_param.size) : cache_entry.stride;
137	  request.max_block_index =
138	      pull_cache_param.prompt_blocks.empty()
139	          ? 0UL
140	          : *std::max_element(pull_cache_param.prompt_blocks.cbegin(), pull_cache_param.prompt_blocks.cend());
141	  request.src_tensor_indices_size = pull_cache_param.src_tensor_indices.size();
142	  request.src_tensor_start_index = 0U;
143	  if (!pull_cache_param.src_tensor_indices.empty()) {
144	    request.src_tensor_start_index = pull_cache_param.src_tensor_indices.front();
145	  }
146	  SetDstAddr(pull_cache_param, cache_entry, request);
147	  LLM_CHK_STATUS_RET(SetBufferInfo(pull_cache_param, cache_entry, contiguous_blocks_pair, request),
148	                     "Failed to set buffer info");
149	  request.req_size = request_size;
150	  return ge::SUCCESS;
151	}
152	
153	ge::Status DataTransferClient::GetResponseInfo() const {
154	  void *resp_addr = comm_entity_->GetEntityInfo().local_resp_ptr;
155	  const auto &response_info = PtrToPtr<void, ResponseInfo>(resp_addr);
156	  LLM_ASSERT_NOTNULL(response_info);
157	  // 校验response里面的数据
158	  auto ret = static_cast<ge::Status>(response_info->ret_code);
159	  LLM_CHK_BOOL_RET_STATUS(ret == ge::SUCCESS, ret, "pull cache failed, not find kv in remote cluster[%lu]",
160	                          comm_entity_->GetClusterId());
161	  LLMLOGD("entity:%s success to receive cache", comm_entity_->GetDesc().c_str());
162	  return ge::SUCCESS;
163	}
164	
165	ge::Status DataTransferClient::SendCacheInfoToRemote() const {
166	  const auto &request = *PtrToPtr<uint8_t, TransferCacheReq>(comm_entity_->GetEntityInfo().send_buffer_req_ptr);
167	  const uint64_t request_size = transfer_message_limits::CalcMinRequestSize(
168	      request.dst_addr_count, request.buffer_info_count, static_cast<uint32_t>(kSrcAndDstNum));
169	  LLM_CHK_BOOL_RET_STATUS(request.req_size == request_size, ge::LLM_PARAM_INVALID,
170	                          "req_size:%lu mismatches expected:%lu, dst_addr_count:%u, buffer_info_count:%u",
171	                          request.req_size, request_size, request.dst_addr_count, request.buffer_info_count);
172	  LLMLOGD("transfer_cache_req size:%lu", request_size);
173	  auto fill_req_func = [request_size](TransferCacheReq &request, uint64_t &size) -> void {
174	    // request already filled, just set size
175	    (void)request;
176	    size = request_size;
177	  };
178	  LLM_CHK_STATUS_RET(comm_entity_->SendRequest(fill_req_func, req_stream_),
179	                     "put cache info to remote_cluster[%lu] failed", comm_entity_->GetClusterId());
180	  return ge::SUCCESS;
181	}
182	
183	ge::Status DataTransferClient::SynchronizeStreamTask(const TimePoint &start_time) const {
184	  LLM_CHK_ACL_RET(aclrtSynchronizeStreamWithTimeout(req_stream_, timeout_in_ms_));
185	  void *local_sync_flag_addr = comm_entity_->GetEntityInfo().local_resp_flag_ptr;
186	  volatile int8_t *volatile local_sync_flag = PtrToPtr<void, int8_t>(local_sync_flag_addr);
187	
188	  while (true) {
189	    const int8_t flag = *local_sync_flag;
190	    if (flag == 1) {
191	      auto &recv_statistic_info = comm_entity_->GetRecvStatisticInfo();
192	      recv_statistic_info.sync_flag_get_times++;
193	      LLMLOGD("entity:%s get sync flag success:%d", comm_entity_->GetDesc().c_str(), static_cast<int32_t>(flag));
194	      break;
195	    }
196	    const auto &current_time = std::chrono::steady_clock::now();
197	    const uint64_t duration = std::chrono::duration_cast<std::chrono::milliseconds>(current_time - start_time).count();
198	    LLM_CHK_BOOL_RET_STATUS(duration <= static_cast<uint64_t>(timeout_in_ms_), ge::LLM_TIMEOUT,
199	                            "entity:%s synchronize timeout, time cost:%lu ms.", comm_entity_->GetDesc().c_str(),
200	                            duration);
201	  }
202	  comm_entity_->ClearResponseFlags();
203	  LLMLOGD("entity:%s synchronize success", comm_entity_->GetDesc().c_str());
204	  return ge::SUCCESS;
205	}
206	
207	ge::Status DataTransferClient::PullCacheFromRemote(const TimePoint &start_time) const {
208	  LLM_CHK_STATUS_RET(SendCacheInfoToRemote(), "send cache info to remote cluster:%lu failed",
209	                     comm_entity_->GetClusterId());
210	  LLM_CHK_STATUS_RET(SynchronizeStreamTask(start_time), "pull cache timeout");
211	  LLM_CHK_STATUS_RET(GetResponseInfo(), "get response failed from remote cluster:%lu", comm_entity_->GetClusterId());
212	  return ge::SUCCESS;
213	}
214	
215	ge::Status DataTransferClient::PullCache(const CacheEntry &cache_entry, const CacheKey &cache_key,
216	                                         const PullCacheParam &pull_cache_param, int32_t timeout_in_ms) {
217	  const auto start = std::chrono::steady_clock::now();
218	  timeout_in_ms_ = timeout_in_ms;
219	  LLM_CHK_STATUS_RET(ConstructTransferInfo(pull_cache_param, cache_entry, cache_key, timeout_in_ms));
220	  LLM_CHK_STATUS_RET(PullCacheFromRemote(start), "Failed to pull kv from remote cluster:%lu",
221	                     cache_key.prompt_cluster_id);
222	  return ge::SUCCESS;
223	}
224	
225	ge::Status DataTransferClient::PullCacheByGet(const CacheEntry &cache_entry, const CacheKey &cache_key,
226	                                              const PullCacheParam &pull_cache_param, int32_t timeout_in_ms) const {
227	  LLM_CHK_STATUS_RET(ConstructTransferInfo(pull_cache_param, cache_entry, cache_key, timeout_in_ms));
228	  const auto &request = comm_entity_->GetRequest();
229	  CacheEntry remote_cache_entry;
230	  LLM_CHK_STATUS_RET(comm_entity_->GetCacheAccessTable().FindCacheEntry(request, remote_cache_entry));
231	  LLM_CHK_BOOL_RET_STATUS(cache_entry.remote_accessible, ge::LLM_PARAM_INVALID,
232	                          "local cache is not remote accessible.");
233	  LLM_CHK_BOOL_RET_STATUS(remote_cache_entry.remote_accessible, ge::LLM_PARAM_INVALID,
234	                          "remote cache is not remote accessible.");
235	  D2DDataTransferJob job;
236	  uint64_t offset = 0;
237	  if (cache_entry.cache_mem_type != CacheMemType::BLOCKS) {
238	    offset += cache_key.prompt_batch_index * cache_entry.stride;
239	  }
240	  LLMLOGD("pull_cache begin from the offset: (%" PRIu64 ").", offset);
241	  LLM_CHK_STATUS_RET(job.Initialize(remote_cache_entry, *comm_entity_, offset));
242	  LLM_CHK_STATUS_RET(job.PullCache(), "Failed to pull cache");
243	  return ge::SUCCESS;
244	}
245	}  // namespace llm
