9	 */
10	
11	#include "data_transfer/d2d_data_transfer_job.h"
12	#include "utils/extern_math_util.h"
13	#include "llm_datadist/llm_error_codes.h"
14	#include "common/def_types.h"
15	#include "common/llm_checker.h"
16	#include "cache_mgr/cache_manager.h"
17	#include "comm_statistic_manager.h"
18	#include "data_transfer/data_transfer_utils.h"
19	#include "acl/acl.h"
20	#include "common/llm_scope_guard.h"
21	
22	namespace llm {
23	namespace {
24	constexpr uint32_t kMaxTaskNum = 1024U;
25	constexpr uint64_t kMaxBatchPutNum = 64U;
26	
27	ge::Status GetSendTask(const CacheEntry &cache_entry, const TransferCacheReq &request, const uint64_t block_size,
28	                       const uint64_t offset, std::list<HcclOneSideOpDesc> &send_tasks) {
29	  const uint64_t remainder = cache_entry.tensor_size % block_size;
30	  const uint64_t num = cache_entry.tensor_size / block_size;
31	  const uint64_t batch_or_block_num = remainder == 0U ? num : num + 1;
32	  uint32_t dst_addr_count = request.dst_addr_count;
33	  const uint32_t buffer_info_count = request.buffer_info_count;
34	  const uint64_t src_layer_range_cache_num = static_cast<uint64_t>(request.src_tensor_indices_size);
35	  const size_t src_addr_num =
36	      (request.src_tensor_indices_size == 0U) ? cache_entry.cache_addrs.size() : src_layer_range_cache_num;
37	  LLM_CHK_BOOL_RET_STATUS(src_addr_num == static_cast<size_t>(dst_addr_count), ge::LLM_PARAM_INVALID,
38	                          "src addr count:%zu, not match received dst_addr_count:%u", src_addr_num, dst_addr_count);
39	  for (size_t i = 0UL; i < src_addr_num; ++i) {
40	    for (uint32_t j = 0U; j < buffer_info_count; ++j) {
41	      HcclOneSideOpDesc hccl_one_side_op_desc;
42	      const auto src_buffer_info = request.transfer_infos[dst_addr_count + j].buffer_info;
43	      const uint64_t src_block_index = src_buffer_info.block_start_index;
44	      const auto dst_buffer_info = request.transfer_infos[dst_addr_count + buffer_info_count + j].buffer_info;
45	      const uint64_t dst_block_index = dst_buffer_info.block_start_index;
46	      LLM_CHK_BOOL_RET_STATUS(src_block_index < batch_or_block_num, ge::LLM_PARAM_INVALID,
47	                              "req_id[%lu], model_id[%lu], src block index[%lu] is out of range[0, %lu)",
48	                              request.req_id, request.model_id, src_block_index, batch_or_block_num);
49	      LLM_CHK_BOOL_RET_STATUS(src_buffer_info.buffer_len == dst_buffer_info.buffer_len, ge::LLM_PARAM_INVALID,
50	                              "req_id[%lu], model_id[%lu], src buffer_len[%lu] not equal dst buffer_len[%lu]",
51	                              request.req_id, request.model_id, src_buffer_info.buffer_len, dst_buffer_info.buffer_len);
52	      // offset is used batch index cache key, if send contiguous to contiguous, block_index is 0
53	      const size_t src_addr_index = i + static_cast<uint64_t>(request.src_tensor_start_index);
54	      hccl_one_side_op_desc.localAddr =
55	          ValueToPtr(PtrToValue(cache_entry.cache_addrs[src_addr_index].get()) + offset + src_block_index * block_size);
56	      // if dst_addr is contiguous, offset is done in pull
57	      hccl_one_side_op_desc.remoteAddr =
58	          ValueToPtr(PtrToValue(request.transfer_infos[i].dst_addr) + dst_block_index * block_size);
59	      const uint64_t target_size = request.is_pull_block == 1U ? cache_entry.tensor_size : cache_entry.stride;
60	      LLM_CHK_BOOL_RET_STATUS(src_buffer_info.buffer_len <= target_size, ge::LLM_PARAM_INVALID,
61	                              "req_id[%lu], model_id[%lu], tensor size (%lu) < required size (%lu)", request.req_id,
62	                              request.model_id, target_size, src_buffer_info.buffer_len);
63	      hccl_one_side_op_desc.count =
64	          (j == buffer_info_count - 1) && (remainder > 0) ? remainder : src_buffer_info.buffer_len;
65	      hccl_one_side_op_desc.dataType = HCCL_DATA_TYPE_INT8;
66	      send_tasks.push_back(std::move(hccl_one_side_op_desc));
67	    }
68	  }
69	  size_t total_num = 0UL;
70	  LLM_ASSERT_TRUE(!ge::MulOverflow(src_addr_num, static_cast<size_t>(buffer_info_count), total_num));
71	  LLM_CHK_BOOL_RET_STATUS(send_tasks.size() == total_num, ge::LLM_PARAM_INVALID,
72	                          "send task size:%zu, not match total num:%zu", send_tasks.size(), total_num);
73	  return ge::SUCCESS;
74	}
75	}  // namespace
76	
77	ge::Status D2DDataTransferJob::Initialize(const CacheEntry &cache_entry, CommEntity &comm_entity, uint64_t offset) {
78	  comm_entity_ = &comm_entity;
79	  LLM_CHK_STATUS_RET(GenerateSendTask(cache_entry, offset), "comm_entity:%s generate send task failed",
80	                     comm_entity.GetDesc().c_str());
81	  timeout_point_ = std::chrono::steady_clock::now();
82	  return ge::SUCCESS;
83	}
84	
85	ge::Status D2DDataTransferJob::Process(bool &is_done) {
86	  aclrtEventRecordedStatus status = ACL_EVENT_RECORDED_STATUS_NOT_READY;
87	  while (status != ACL_EVENT_RECORDED_STATUS_COMPLETE) {
88	    if (std::chrono::steady_clock::now() > comm_entity_->GetTimeoutPoint()) {
89	      LLM_CHK_STATUS_RET(comm_entity_->SendResponse(ge::LLM_TIMEOUT));
90	      LLMLOGE(ge::LLM_TIMEOUT, "handle request timeout");
91	      return ge::LLM_TIMEOUT;
92	    }
93	    LLM_CHK_STATUS_RET(DataTransferUtils::QueryEventStatus(event_, status), "comm_entity:%s query event status failed",
94	                       comm_entity_->GetDesc().c_str());
95	    LLMLOGI("QueryEventStatus ret=%d", status);
96	  }
97	  if (event_ != nullptr) {
98	    LLM_ASSERT_RT_OK(aclrtDestroyEvent(event_));
99	    event_ = nullptr;
100	  }
101	  if (send_tasks_.empty()) {
102	    LLM_CHK_STATUS_RET(comm_entity_->SendResponse(ge::SUCCESS));
103	    is_done = true;
104	    const auto finished_time_point = std::chrono::steady_clock::now();
105	    const auto cost = static_cast<uint64_t>(
106	        std::chrono::duration_cast<std::chrono::microseconds>(finished_time_point - timeout_point_).count());
107	    auto &send_statistic_info = comm_entity_->GetSendStatisticInfo();
108	    CommStatisticManager::GetInstance().UpdateCost(cost, send_statistic_info.send_times,
109	                                                   send_statistic_info.send_min_cost, send_statistic_info.send_max_cost,
110	                                                   send_statistic_info.send_total_cost);
111	    LLMLOGI("comm_entity:%s send all task of request finished", comm_entity_->GetDesc().c_str());
112	    return ge::SUCCESS;
113	  }
114	  LLM_CHK_STATUS_RET(DataTransferUtils::SendCache(comm_entity_->GetStream(), *comm_entity_, send_tasks_, event_),
115	                     "comm_entity:%s send cache failed", comm_entity_->GetDesc().c_str());
116	  return ge::SUCCESS;
117	}
118	
119	ge::Status D2DDataTransferJob::GenerateCacheTask(const CacheEntry &cache_entry, const TransferCacheReq &request,
120	                                                 const uint64_t offset) {
121	  if (request.is_pull_block == 1U) {
122	    LLM_CHK_BOOL_RET_STATUS(request.block_size != 0U, ge::LLM_PARAM_INVALID,
123	                            "req:%lu, model_id:%lu, block size(%lu) is invalid", request.req_id, request.model_id,
124	                            request.block_size);
125	  }
126	  uint64_t stride_or_block_size = (request.block_size != 0U) ? request.block_size : cache_entry.stride;
127	  const auto ret = GetSendTask(cache_entry, request, stride_or_block_size, offset, send_tasks_);
128	  LLM_CHK_STATUS_RET(ret, "comm_entity:%s get send task failed", comm_entity_->GetDesc().c_str());
129	  return ge::SUCCESS;
130	}
131	
132	ge::Status D2DDataTransferJob::GenerateSendTask(const CacheEntry &cache_entry, const uint64_t offset) {
133	  // 解析本地地址上发送过来的cache info
134	  const TransferCacheReq &request = comm_entity_->GetRequest();
135	  return GenerateCacheTask(cache_entry, request, offset);
136	}
137	
138	ge::Status D2DDataTransferJob::PullCache() {
139	  LLM_CHK_STATUS_RET(comm_entity_->BatchTransfer(send_tasks_, false, true, comm_entity_->GetRequest().timeout_in_ms),
140	                     "Failed to batch get, task size:%zu.", send_tasks_.size());
141	  return ge::SUCCESS;
142	}
143	}  // namespace llm
