16	
17	namespace llm {
18	namespace {
19	constexpr uint32_t kMaxTaskNum = 1024U;
20	constexpr uint64_t kMaxBatchPutNum = 64U;
21	constexpr uint64_t kBlocksCacheKey = 1UL;
22	constexpr uint64_t kCacheKeyByIdType = 2UL;
23	}  // namespace
24	LayerWiseTransferJob::LayerWiseTransferJob(CommEntity &comm_entity, aclrtStream stream)
25	    : stream_(stream), comm_entity_(&comm_entity) {}
26	
27	ge::Status LayerWiseTransferJob::GenerateCacheToCacheTask(const CacheEntry &cache_entry,
28	                                                          const std::vector<std::shared_ptr<void>> &src_layer_addrs,
29	                                                          const TransferCacheConfig &transfer_cache_config) {
30	  const uint64_t batch_index = transfer_cache_config.batch_index;
31	  LLM_CHK_BOOL_RET_STATUS(batch_index < static_cast<uint64_t>(cache_entry.batch_size), ge::LLM_PARAM_INVALID,
32	                          "batch index[%lu] is out of range[0, %u)", batch_index, cache_entry.batch_size);
33	  const uint64_t offset = batch_index * cache_entry.stride;
34	  for (size_t i = 0UL; i < src_layer_addrs.size(); ++i) {
35	    HcclOneSideOpDesc layer_desc;
36	    layer_desc.localAddr = ValueToPtr(PtrToValue(src_layer_addrs[i].get()) + offset);
37	    layer_desc.remoteAddr = ValueToPtr(transfer_cache_config.dst_addrs[i]);
38	    layer_desc.count = cache_entry.stride;
39	    layer_desc.dataType = HCCL_DATA_TYPE_INT8;
40	    layer_transfer_tasks_.push_back(layer_desc);
41	  }
42	  return ge::SUCCESS;
43	}
44	
45	ge::Status LayerWiseTransferJob::GenerateCacheToBlocksTask(const CacheEntry &cache_entry,
46	                                                           const std::vector<std::shared_ptr<void>> &src_layer_addrs,
47	                                                           const TransferCacheConfig &transfer_cache_config,
48	                                                           const TransferBlockConfig &transfer_block_config) {
49	  LLM_CHK_BOOL_RET_STATUS(
50	      (transfer_block_config.block_mem_size > 0U) && (transfer_block_config.block_mem_size < cache_entry.tensor_size),
51	      ge::LLM_PARAM_INVALID,
52	      "block_mem_size[%lu] must > 0 and < tensor size[%lu] when transfer from continuous cache to blocks",
53	      transfer_block_config.block_mem_size, cache_entry.tensor_size);
54	  const uint64_t batch_index = transfer_cache_config.batch_index;
55	  LLM_CHK_BOOL_RET_STATUS(batch_index < static_cast<uint64_t>(cache_entry.batch_size), ge::LLM_PARAM_INVALID,
56	                          "batch index[%lu] is out of range[0, %u)", batch_index, cache_entry.batch_size);
57	  const uint64_t offset = batch_index * cache_entry.stride;
58	  const uint64_t remainder = cache_entry.tensor_size % transfer_block_config.block_mem_size;
59	  const uint64_t num = cache_entry.tensor_size / transfer_block_config.block_mem_size;
60	  const uint64_t block_num = (remainder == 0U) ? num : num + 1;
61	  const size_t dst_blocks_num = transfer_block_config.dst_blocks.size();
62	  LLM_CHK_BOOL_RET_STATUS(block_num >= dst_blocks_num, ge::LLM_PARAM_INVALID,
63	                          "The number[%lu] after splitting contiguous memory by size[%lu] < the dst_block num[%zu].",
64	                          block_num, transfer_block_config.block_mem_size, dst_blocks_num);
65	  LLMLOGI("The number after splitting contiguous memory by size[%lu] is:%lu, dst_block num[%zu].",
66	          transfer_block_config.block_mem_size, block_num, dst_blocks_num);
67	  for (size_t i = 0UL; i < src_layer_addrs.size(); ++i) {
68	    const auto src_layer_addr = src_layer_addrs[i];
69	    for (size_t j = 0UL; j < dst_blocks_num; ++j) {
70	      HcclOneSideOpDesc layer_desc;
71	      layer_desc.localAddr =
72	          ValueToPtr(PtrToValue(src_layer_addr.get()) + offset + j * transfer_block_config.block_mem_size);
73	      layer_desc.remoteAddr = ValueToPtr(transfer_cache_config.dst_addrs[i] +
74	                                         transfer_block_config.dst_blocks[j] * transfer_block_config.block_mem_size);
75	      layer_desc.count =
76	          ((j == dst_blocks_num - 1) && (remainder > 0U)) ? remainder : transfer_block_config.block_mem_size;
77	      layer_desc.dataType = HCCL_DATA_TYPE_INT8;
78	      layer_transfer_tasks_.push_back(layer_desc);
79	    }
80	  }
81	  return ge::SUCCESS;
82	}
83	
84	ge::Status LayerWiseTransferJob::GenerateBlocksToBlocksTask(const CacheEntry &cache_entry,
85	                                                            const std::vector<std::shared_ptr<void>> &src_layer_addrs,
86	                                                            const TransferCacheConfig &transfer_cache_config,
87	                                                            const TransferBlockConfig &transfer_block_config) {
88	  LLM_CHK_BOOL_RET_STATUS(cache_entry.num_blocks > 0, ge::LLM_PARAM_INVALID,
89	                          "check failed, request expect local cache is blocks");
90	  std::vector<std::vector<std::pair<int64_t, int64_t>>> contiguous_blocks_pair;
91	  LLM_CHK_STATUS_RET(LLMUtils::FindContiguousBlockIndexPair(transfer_block_config.src_blocks,
92	                                                            transfer_block_config.dst_blocks, contiguous_blocks_pair));
93	  if (transfer_block_config.block_mem_size > 0U) {
94	    LLM_CHK_BOOL_RET_STATUS(cache_entry.stride == transfer_block_config.block_mem_size, ge::LLM_PARAM_INVALID,
95	                            "block_mem_size[%lu] is not match cache stride:%lu", transfer_block_config.block_mem_size,
96	                            cache_entry.stride);
97	  }
98	  for (size_t i = 0UL; i < src_layer_addrs.size(); ++i) {
99	    const auto src_layer_addr = src_layer_addrs[i];
100	    const auto dst_layer_addr = transfer_cache_config.dst_addrs[i];
101	    for (const auto &blocks_pair : contiguous_blocks_pair) {
102	      LLM_CHK_BOOL_RET_STATUS((static_cast<uint64_t>(blocks_pair.front().first) < cache_entry.num_blocks) &&
103	                                  (static_cast<uint64_t>(blocks_pair.back().first) < cache_entry.num_blocks),
104	                              ge::LLM_PARAM_INVALID, "src block index[%ld] or [%ld] is out of range [0, %lu)",
105	                              blocks_pair.front().first, blocks_pair.back().first, cache_entry.num_blocks);
106	      HcclOneSideOpDesc layer_desc;
107	      layer_desc.localAddr =
108	          ValueToPtr(PtrToValue(src_layer_addr.get()) + blocks_pair.front().first * cache_entry.stride);
109	      layer_desc.remoteAddr = ValueToPtr(dst_layer_addr + blocks_pair.front().second * cache_entry.stride);
110	      layer_desc.count = cache_entry.stride * blocks_pair.size();
111	      LLMLOGI("transfer from src block index[%lu] to dst block index[%lu], block size:%lu", blocks_pair.front().first,
112	              blocks_pair.front().second, layer_desc.count);
113	      layer_desc.dataType = HCCL_DATA_TYPE_INT8;
114	      layer_transfer_tasks_.push_back(layer_desc);
115	    }
116	  }
117	  return ge::SUCCESS;
118	}
119	
120	ge::Status LayerWiseTransferJob::Prepare(const CacheEntry &cache_entry,
121	                                         const TransferCacheConfig &transfer_cache_config,
122	                                         const TransferBlockConfig &transfer_block_config) {
123	  const auto &src_cache_addrs = cache_entry.cache_addrs;
124	  const uint64_t layer_index = transfer_cache_config.layer_index;
125	  const uint64_t layer_num = src_cache_addrs.size() / transfer_cache_config.tensor_num_per_layer;
126	  LLM_CHK_BOOL_RET_STATUS(layer_index < layer_num, ge::LLM_PARAM_INVALID, "layer index[%lu] is out of range[0, %lu)",
127	                          layer_index, layer_num);
128	  const size_t remainder = src_cache_addrs.size() % transfer_cache_config.tensor_num_per_layer;
129	  LLM_CHK_BOOL_RET_STATUS(
130	      remainder == 0U, ge::LLM_PARAM_INVALID,
131	      "When using layer wise transfer, the tensor_num [%zu] of caches must be a multiple of tensor_num_per_layer[%lu].",
132	      src_cache_addrs.size(), transfer_cache_config.tensor_num_per_layer);
133	  const std::vector<std::shared_ptr<void>> src_layer_addrs(
134	      src_cache_addrs.begin() + layer_index * transfer_cache_config.tensor_num_per_layer,
135	      src_cache_addrs.begin() + layer_index * transfer_cache_config.tensor_num_per_layer +
136	          transfer_cache_config.tensor_num_per_layer);
137	  LLM_CHK_BOOL_RET_STATUS(src_layer_addrs.size() == transfer_cache_config.dst_addrs.size(), ge::LLM_PARAM_INVALID,
138	                          "src_layer_addrs size[%zu] is not match dst_addrs size[%zu]", src_layer_addrs.size(),
139	                          transfer_cache_config.dst_addrs.size());
140	  if (transfer_block_config.dst_blocks.empty()) {
141	    LLM_CHK_STATUS_RET(GenerateCacheToCacheTask(cache_entry, src_layer_addrs, transfer_cache_config));
142	  } else if (transfer_block_config.src_blocks.empty()) {
143	    LLM_CHK_STATUS_RET(
144	        GenerateCacheToBlocksTask(cache_entry, src_layer_addrs, transfer_cache_config, transfer_block_config));
145	  } else {
146	    LLM_CHK_STATUS_RET(
147	        GenerateBlocksToBlocksTask(cache_entry, src_layer_addrs, transfer_cache_config, transfer_block_config));
148	  }
149	  return ge::SUCCESS;
150	}
151	
152	ge::Status LayerWiseTransferJob::SynchronizeTransferCacheWithRecord(const int32_t timeout_in_ms) {
153	  const auto start = std::chrono::steady_clock::now();
154	  while (!layer_transfer_tasks_.empty()) {
155	    LLM_CHK_STATUS_RET(DataTransferUtils::SendCache(stream_, *comm_entity_, layer_transfer_tasks_, event_),
156	                       "comm_entity:%s send cache failed", comm_entity_->GetDesc().c_str());
157	    aclrtEventRecordedStatus status = ACL_EVENT_RECORDED_STATUS_NOT_READY;
158	    while (status != ACL_EVENT_RECORDED_STATUS_COMPLETE) {
159	      if (std::chrono::steady_clock::now() > start + std::chrono::milliseconds(timeout_in_ms)) {
160	        LLMLOGE(ge::LLM_TIMEOUT, "stream handle transfer request timeout");
161	        return ge::LLM_TIMEOUT;
162	      }
163	      LLM_CHK_STATUS_RET(DataTransferUtils::QueryEventStatus(event_, status),
164	                         "comm_entity:%s query event status failed", comm_entity_->GetDesc().c_str());
165	      LLMLOGI("query event status ret=%d", status);
166	    }
167	    if (event_ != nullptr) {
168	      LLM_ASSERT_RT_OK(aclrtDestroyEvent(event_));
169	      event_ = nullptr;
170	    }
171	  }
172	  LLM_CHK_ACL_RET(aclrtSynchronizeStreamWithTimeout(stream_, timeout_in_ms));
173	
174	  const auto finished = std::chrono::steady_clock::now();
175	  const auto cost =
176	      static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::microseconds>(finished - start).count());
177	  auto &send_statistic_info = comm_entity_->GetSendStatisticInfo(stream_);
178	  CommStatisticManager::GetInstance().UpdateCost(cost, send_statistic_info.send_times,
179	                                                 send_statistic_info.send_min_cost, send_statistic_info.send_max_cost,
180	                                                 send_statistic_info.send_total_cost);
181	  LLMLOGI("comm_entity:%s send all task of request finished", comm_entity_->GetDesc().c_str());
182	  return ge::SUCCESS;
183	}
184	
185	ge::Status LayerWiseTransferJob::FillRemoteLayerAddrs(int32_t timeout_in_ms, TransferCacheConfig &transfer_config,
186	                                                      const TransferBlockConfig &transfer_block_config) const {
187	  TransferCacheReq request{};
188	  request.timeout_in_ms = timeout_in_ms;
189	  if (transfer_config.type == kBlocksCacheKey) {
190	    request.req_id = UINT64_MAX;
191	    request.model_id = transfer_config.model_id_or_cache_id;
192	  } else if (transfer_config.type == kCacheKeyByIdType) {
193	    request.cache_id = static_cast<int64_t>(transfer_config.model_id_or_cache_id);
194	  } else {
195	  }
196	  CacheEntry remote_cache_entry;
197	  LLM_CHK_STATUS_RET(comm_entity_->GetCacheAccessTable().FindCacheEntry(request, remote_cache_entry));
198	  LLM_CHK_STATUS_RET(ValidateRemoteCache(remote_cache_entry, transfer_config, transfer_block_config),
199	                     "Validate remote cache failed.");
200	  auto begin_index =
201	      remote_cache_entry.cache_addrs.begin() + transfer_config.dst_layer_index * transfer_config.tensor_num_per_layer;
202	  const std::vector<std::shared_ptr<void>> dst_layer_addrs(begin_index,
203	                                                           begin_index + transfer_config.tensor_num_per_layer);
204	  for (auto &cache_addr : dst_layer_addrs) {
205	    transfer_config.dst_addrs.emplace_back(reinterpret_cast<uintptr_t>(cache_addr.get()) +
206	                                           transfer_config.dst_batch_index * remote_cache_entry.stride);
207	  }
208	  LLMLOGI("Transfer type:%lu, model_or_cache_id:%lu, dst_layer_index:%lu.", transfer_config.type,
209	          transfer_config.model_id_or_cache_id, transfer_config.dst_layer_index);
210	  return ge::SUCCESS;
211	}
212	
213	ge::Status LayerWiseTransferJob::ValidateRemoteCache(const CacheEntry &remote_cache_entry,
214	                                                     const TransferCacheConfig &transfer_cache_config,
215	                                                     const TransferBlockConfig &transfer_block_config) const {
216	  LLM_CHK_BOOL_RET_STATUS(remote_cache_entry.remote_accessible, ge::LLM_PARAM_INVALID,
217	                          "remote cache is not remote accessible.");
218	  // validate layer_index
219	  const uint64_t layer_num = remote_cache_entry.cache_addrs.size() / transfer_cache_config.tensor_num_per_layer;
220	  LLM_CHK_BOOL_RET_STATUS(transfer_cache_config.dst_layer_index < layer_num, ge::LLM_PARAM_INVALID,
221	                          "layer index[%lu] is out of range[0, %lu)", transfer_cache_config.dst_layer_index, layer_num);
222	  if (transfer_block_config.dst_blocks.empty()) {
223	    // C2C
224	    const uint64_t batch_index = transfer_cache_config.dst_batch_index;
225	    LLM_CHK_BOOL_RET_STATUS(batch_index < static_cast<uint64_t>(remote_cache_entry.batch_size), ge::LLM_PARAM_INVALID,
226	                            "batch index[%lu] is out of range[0, %u) of remote cache.", batch_index,
227	                            remote_cache_entry.batch_size);
228	  } else {
229	    auto max_ele = std::max_element(transfer_block_config.dst_blocks.cbegin(), transfer_block_config.dst_blocks.cend());
230	    LLM_CHK_BOOL_RET_STATUS((*max_ele < remote_cache_entry.num_blocks), ge::LLM_PARAM_INVALID,
231	                            "dst block index[%ld] is out of range [0, %lu)", *max_ele, remote_cache_entry.num_blocks);
232	    LLM_CHK_BOOL_RET_STATUS((transfer_block_config.block_mem_size == 0) ||
233	                                (transfer_block_config.block_mem_size == remote_cache_entry.stride),
234	                            ge::LLM_PARAM_INVALID,
235	                            "dst_block_memory_size[%lu] is not equal to stride[%lu] of remote cache.",
236	                            transfer_block_config.block_mem_size, remote_cache_entry.stride);
237	  }
238	  return ge::SUCCESS;
239	}
240	
241	ge::Status LayerWiseTransferJob::TransferCache(const CacheEntry &cache_entry,
242	                                               const TransferCacheConfig &transfer_cache_config,
243	                                               const TransferBlockConfig &transfer_block_config, int32_t timeout_in_ms,
244	                                               bool access_remote_cache) {
245	  TransferCacheConfig transfer_config = transfer_cache_config;
246	  LLM_DISMISSABLE_GUARD(stream, [this]() -> void { LLM_CHK_ACL(aclrtStreamAbort(comm_entity_->GetStream())); });
247	  if (access_remote_cache) {
248	    LLM_CHK_BOOL_RET_STATUS(cache_entry.remote_accessible, ge::LLM_PARAM_INVALID,
249	                            "local cache is not remote accessible.");
250	    LLM_CHK_STATUS_RET(FillRemoteLayerAddrs(timeout_in_ms, transfer_config, transfer_block_config),
251	                       "Fill remote addrs failed.");
252	  }
253	  LLM_CHK_STATUS_RET(Prepare(cache_entry, transfer_config, transfer_block_config), "prepare transfer task failed");
254	  if (access_remote_cache) {
255	    LLM_CHK_STATUS_RET(comm_entity_->BatchTransfer(layer_transfer_tasks_, true, false, timeout_in_ms),
256	                       "Failed to batch put, task size:%zu.", layer_transfer_tasks_.size());
257	    LLMLOGI("comm_entity:%s send all task of request finished", comm_entity_->GetDesc().c_str());
258	  } else {
259	    LLM_CHK_STATUS_RET(SynchronizeTransferCacheWithRecord(timeout_in_ms), "transfer cache with record failed");
260	  }
261	  LLM_DISMISS_GUARD(stream);
262	  return ge::SUCCESS;
263	}
264	
265	}  // namespace llm
