30	ge::Status ValidateD2HClientPullLayout(uint32_t dst_addr_count, size_t prompt_block_count, uint64_t &request_size) {
31	  using namespace transfer_message_limits;
32	  LLM_CHK_BOOL_RET_STATUS(dst_addr_count > 0U, ge::LLM_PARAM_INVALID, "dst_addr_count is 0");
33	  LLM_CHK_BOOL_RET_STATUS(prompt_block_count <= kMaxBlockNum, ge::LLM_PARAM_INVALID,
34	                          "number of prompt blocks (%zu) out of bound, at most %zu is supported", prompt_block_count,
35	                          kMaxBlockNum);
36	  const uint64_t max_prompt_blocks = MaxD2hPromptBlocksForDstCount(dst_addr_count);
37	  LLM_CHK_BOOL_RET_STATUS(prompt_block_count <= max_prompt_blocks, ge::LLM_PARAM_INVALID,
38	                          "number of prompt blocks (%zu) exceeds request buffer limit (%lu), dst_addr_count:%u",
39	                          prompt_block_count, max_prompt_blocks, dst_addr_count);
40	  const uint64_t transfer_info_count = static_cast<uint64_t>(dst_addr_count) + prompt_block_count;
41	  LLM_CHK_BOOL_RET_STATUS(transfer_info_count <= kMaxTransferInfoCount, ge::LLM_PARAM_INVALID,
42	                          "transfer info count:%lu exceeds max:%lu", transfer_info_count, kMaxTransferInfoCount);
43	  request_size =
44	      CalcMinRequestSize(dst_addr_count, static_cast<uint32_t>(prompt_block_count), kBufferInfoMultiplierD2h);
45	  LLM_CHK_BOOL_RET_STATUS(request_size <= kMaxRequestPayloadSize, ge::LLM_PARAM_INVALID,
46	                          "request size:%lu exceeds max:%lu (buffer:%lu - flag:%lu), "
47	                          "dst_addr_count:%u, prompt_blocks:%zu",
48	                          request_size, kMaxRequestPayloadSize, kDefaultReqBufferSize, kMsgFlagSize, dst_addr_count,
49	                          prompt_block_count);
50	  return ge::SUCCESS;
51	}
52	
53	struct BlockTaskGenState {
54	  TransferBlocksTask *prev_task = nullptr;
55	  uint64_t prev_block_index = UINT64_MAX;
56	  uint32_t buffer_index = 0;
57	  uint32_t prev_buffer_index = UINT32_MAX;
58	  uint32_t buffer_block_index = 0;
59	};
60	
61	bool AppendBlockTransferTask(std::vector<TransferBlocksTask> &ret, BlockTaskGenState &state, uint32_t tensor_index,
62	                             uint32_t block_size, uint64_t block_index, uint32_t cur_block_size,
63	                             uint32_t max_block_size) {
64	  if (state.buffer_index != state.prev_buffer_index) {
65	    ret.emplace_back(TransferBlocksTask{kTaskTypeStartBlock, state.buffer_index, TransferBlockSpan{}});
66	  }
67	  state.prev_buffer_index = state.buffer_index;
68	  if ((state.prev_task != nullptr) && (state.prev_block_index != UINT64_MAX) &&
69	      (block_index == state.prev_block_index + 1U) &&
70	      state.prev_task->block_span.size + static_cast<uint32_t>(cur_block_size) <= max_block_size) {
71	    state.prev_task->block_span.size += static_cast<uint32_t>(cur_block_size);
72	    return true;
73	  }
74	  const auto tensor_offset = block_index * block_size;
75	  ret.emplace_back(
76	      TransferBlocksTask{kTaskTypeTransferBlock, state.buffer_index,
77	                         TransferBlockSpan{state.buffer_block_index, tensor_offset, tensor_index, cur_block_size}});
78	  state.prev_task = &ret.back();
79	  return false;
80	}
81	
82	void FinalizeTransferTasks(std::vector<TransferBlocksTask> &ret, uint32_t buffer_block_index, uint32_t buffer_index,
83	                           std::vector<uint32_t> &buffer_block_nums) {
84	  if (buffer_block_index > 0) {
85	    buffer_block_nums.emplace_back(buffer_block_index);
86	  }
87	  if ((!ret.empty()) && (ret.back().task_type != kTaskTypeEndBlock)) {
88	    ret.emplace_back(TransferBlocksTask{kTaskTypeEndBlock, buffer_index, TransferBlockSpan{}});
89	  }
90	}
91	
92	void AppendLargeBlockChunkTasks(std::vector<TransferBlocksTask> &ret, uint32_t buffer_index, uint32_t tensor_index,
93	                                uint32_t block_size, uint64_t block_index, uint32_t chunk_buffer_size) {
94	  auto tensor_offset = block_index * block_size;
95	  auto remaining_block_size = block_size;
96	  while (remaining_block_size > 0) {
97	    const auto cur_block_size = std::min(remaining_block_size, chunk_buffer_size);
98	    ret.emplace_back(TransferBlocksTask{kTaskTypeStartBlock, buffer_index, TransferBlockSpan{}});
99	    ret.emplace_back(TransferBlocksTask{kTaskTypeTransferBlock, buffer_index,
100	                                        TransferBlockSpan{0, tensor_offset, tensor_index, cur_block_size}});
101	    remaining_block_size -= cur_block_size;
102	    tensor_offset += cur_block_size;
103	    ret.emplace_back(TransferBlocksTask{kTaskTypeEndBlock, buffer_index, TransferBlockSpan{}});
104	  }
105	}
