114	ge::Status D2HDataTransferJob::Initialize(const CacheEntry &cache_entry, CommEntity &comm_entity, uint64_t offset) {
115	  stream_ = comm_entity.GetStream();
116	  buffered_sender_.Initialize(comm_entity);
117	  const auto &req = comm_entity.GetRequest();
118	  const auto resp_len = transfer_message_limits::CalcResponseSize(req.dst_addr_count);
119	  auto *local_recv_flag_addr_base = PtrToPtr<void, uint8_t>(comm_entity.GetEntityInfo().local_resp_ptr) + resp_len;
120	  // Derive the remote recv-flag base from the already-validated request layout (dst_addr_count / buffer_info_count are
121	  // bounded by SendState::ValidateTransferRequest) instead of trusting the wire req_size. For well-behaved peers this
122	  // equals req.req_size; for a forged req_size it prevents redirecting the remote one-sided write outside the peer
123	  // request buffer.
124	  const uint64_t req_layout_size = transfer_message_limits::CalcMinRequestSize(
125	      req.dst_addr_count, req.buffer_info_count, transfer_message_limits::kBufferInfoMultiplierD2h);
126	  auto *remote_recv_flag_addr_base =
127	      PtrToPtr<void, uint8_t>(comm_entity.GetEntityInfo().remote_req_ptr) + req_layout_size;
128	  std::vector<uint64_t> sync_flag_addresses;
129	  for (uint32_t i = 0U; i < req.dst_addr_count; ++i) {
130	    dst_buffers_.emplace_back(PtrToPtr<void, uint8_t>(req.transfer_infos[i].dst_addr));
131	    auto remote_recv_flag_addr = remote_recv_flag_addr_base + sizeof(int32_t) * i;
132	    dst_receive_flag_addresses_.emplace_back(remote_recv_flag_addr);
133	    auto recv_flag_addr = PtrToPtr<uint8_t, int32_t>(local_recv_flag_addr_base + sizeof(int32_t) * i);
134	    *recv_flag_addr = 1;  // 第一次不需要等待
135	    receive_flags_.emplace_back(recv_flag_addr);
136	    sync_flag_addresses.emplace_back(PtrToValue(recv_flag_addr));
137	  }
138	  send_sync_flag_ = PtrToPtr<void, uint8_t>(comm_entity.GetEntityInfo().send_dev_buffer_resp_ptr) + resp_len;
139	  auto send_sync_host_flag_ = static_cast<uint8_t>(1U);
140	  LLM_CHK_ACL_RET(
141	      aclrtMemcpy(send_sync_flag_, sizeof(uint8_t), &send_sync_host_flag_, sizeof(uint8_t), ACL_MEMCPY_HOST_TO_DEVICE));
142	
143	  size_t start_index = 0U;
144	  size_t end_index = 0U;
145	  if (req.src_tensor_indices_size == 0U) {
146	    end_index = cache_entry.cache_addrs.size();
147	  } else {
148	    start_index = static_cast<size_t>(req.src_tensor_start_index);
149	    end_index = start_index + static_cast<size_t>(req.src_tensor_indices_size);
150	  }
151	  for (; start_index < end_index; ++start_index) {
152	    data_addresses_.emplace_back(PtrToPtr<void, uint8_t>(cache_entry.cache_addrs[start_index].get()) + offset);
153	  }
154	
155	  LLM_CHK_STATUS_RET(ResolveBlockSize(req, cache_entry));
156	  LLM_CHK_STATUS_RET(GenerateTasks(req, cache_entry));
157	  sync_buffer_events_.resize(req.dst_addr_count);
158	  const auto ret =
159	      comm_entity.SendResponse([this, resp_len, &sync_flag_addresses](ResponseInfo &resp, uint64_t &size) -> void {
160	        size = resp_len;
161	        resp.ret_code = ge::SUCCESS;
162	        resp.block_size = block_size_;
163	        for (size_t i = 0U; i < sync_flag_addresses.size(); ++i) {
164	          resp.sync_flag_addresses[i] = sync_flag_addresses[i];
165	        }
166	      });
167	  LLM_CHK_STATUS_RET(ret, "Failed to send response");
168	  LLMLOGD("Initialize successfully, send response, size = %zu", resp_len);
169	  return ge::SUCCESS;
170	}
