172	ge::Status D2HDataTransferJob::Process(bool &is_done) {
173	  LLMLOGD("Process In, current_task_index = %zu, total = %zu", current_index_, tasks_.size());
174	  // 查询是否发送完成
175	  auto task_index = current_index_;
176	  for (; task_index < tasks_.size(); ++task_index) {
177	    const auto &task = tasks_[task_index];
178	    if (task.task_type == kTaskTypeStartBlock) {
179	      auto &sync_flag = receive_flags_[task.buffer_index];
180	      if (sync_flag.Check() != ge::SUCCESS) {
181	        // need schedule next time.
182	        return ge::SUCCESS;
183	      }
184	      LLMLOGD("Buffer[%u] wait sync flag success", task.buffer_index);
185	    } else if (task.task_type == kTaskTypeTransferBlock) {
186	      auto buffer_index = task.buffer_index;
187	      auto src_addr = data_addresses_[task.block_span.tensor_index] + task.block_span.tensor_offset;
188	      auto dst_addr = dst_buffers_[buffer_index] + task.block_span.buffer_block_start * block_size_;
189	      LLM_CHK_STATUS_RET(buffered_sender_.Put(src_addr, dst_addr, task.block_span.size));
190	      LLMLOGD("Buffer[%u] [Transfer] tensor_index:%u, src_offset = %lu, dst_offset = %lu, size = %u", task.buffer_index,
191	              task.block_span.tensor_index, task.block_span.tensor_offset,
192	              task.block_span.buffer_block_start * block_size_, task.block_span.size);
193	    } else if (task.task_type == kTaskTypeEndBlock) {
194	      LLM_CHK_STATUS_RET(buffered_sender_.Flush(), "Failed to transfer data");
195	      LLM_CHK_STATUS_RET(
196	          buffered_sender_.Put(send_sync_flag_, dst_receive_flag_addresses_[task.buffer_index], 1, true));
197	      LLMLOGD("Buffer[%u] put async done", task.buffer_index);  // in transfer_stream
198	    } else {
199	      // no op
200	    }
201	
202	    ++current_index_;
203	  }
204	
205	  // 全部task下发完成, 记录event
206	  if (event_ == nullptr) {
207	    LLM_CHK_ACL_RET(aclrtCreateEvent(&event_));
208	    LLM_CHK_ACL_RET(aclrtRecordEvent(event_, stream_));
209	  }
210	  aclrtEventRecordedStatus event_status{};
211	  LLM_CHK_ACL_RET(aclrtQueryEventStatus(event_, &event_status));
212	  if (event_status != ACL_EVENT_RECORDED_STATUS_COMPLETE) {
213	    // 没有wait到，等待下一次
214	    LLMLOGD("event not recorded");
215	    return ge::SUCCESS;
216	  }
217	  // all task done
218	  LLMLOGD("pull cache done");
219	  is_done = true;
220	  return ge::SUCCESS;
221	}
