223	ge::Status D2HDataTransferJob::GenerateTasks(const TransferCacheReq &req, const CacheEntry &cache_entry) {
224	  DataTransferTaskGenerator task_generator(static_cast<uint32_t>(data_addresses_.size()), req.dst_addr_count,
225	                                           req.dst_buffer_size);
226	  if (cache_entry.num_blocks == 0U) {
227	    // local is cont.
228	    tasks_ = task_generator.GenerateTasks(tensor_size_, block_size_);
229	  } else {
230	    //  local is blocks
231	    std::vector<uint64_t> block_indices;
232	    LLM_CHK_BOOL_RET_STATUS(req.buffer_info_count > 0, ge::LLM_PARAM_INVALID, "buffer_info_count is 0");
233	    block_indices.reserve(req.buffer_info_count);
234	    for (uint32_t i = 0U; i < req.buffer_info_count; ++i) {
235	      block_indices.emplace_back(req.transfer_infos[req.dst_addr_count + i].buffer_info.block_start_index);
236	    }
237	    tasks_ =
238	        task_generator.GenerateTasks(block_size_, static_cast<uint32_t>(block_indices.size()), block_indices.data());
239	  }
240	  if (LlmIsLogEnable(LLM_MODULE_NAME, DLOG_DEBUG)) {
241	    PrintTasks(tasks_);
242	  }
243	  return ge::SUCCESS;
244	}
