263	ge::Status D2HDataTransferJob::ResolveBlockSize(const TransferCacheReq &request, const CacheEntry &cache_entry) {
264	  tensor_size_ = static_cast<int64_t>(request.pull_size);
265	  if (request.block_size != 0) {
266	    // dst is blocks
267	    block_size_ = request.block_size;
268	    if (cache_entry.num_blocks != 0) {
269	      // blocks to blocks, check block size
270	      LLM_CHK_BOOL_RET_STATUS(request.block_size == cache_entry.stride, ge::LLM_PARAM_INVALID,
271	                              "block size mismatches, in req = %lu, local = %lu", request.block_size,
272	                              cache_entry.stride);
273	    } else {
274	      // cont. to blocks
275	      tensor_size_ = std::min(tensor_size_, static_cast<int64_t>(cache_entry.stride));
276	    }
277	  } else {
278	    // dst is cont.
279	    LLM_CHK_BOOL_RET_STATUS(tensor_size_ > 0, ge::LLM_PARAM_INVALID, "request tensor size == 0");
280	    LLM_CHK_BOOL_RET_STATUS(cache_entry.num_blocks == 0, ge::LLM_PARAM_INVALID,
281	                            "Blocks to continuous memory is not supported by D2H data transfer");
282	    // cont. to cont.
283	    block_size_ = kBlockSizeForContMem;
284	  }
285	  LLMLOGD("tensor_size = %ld, block_size = %u", tensor_size_, block_size_);
286	  return ge::SUCCESS;
287	}
