289	std::vector<TransferBlocksTask> DataTransferTaskGenerator::DoGenerate(uint32_t block_size, uint32_t tail_block_size,
290	                                                                      uint32_t num_block_indices,
291	                                                                      const uint64_t *block_indices) {
292	  std::vector<TransferBlocksTask> ret;
293	  const uint32_t buffer_block_num = buffer_size_ / block_size;
294	  BlockTaskGenState state{};
295	  std::set<uint32_t> used_buffer_indices;
296	  uint32_t num_transfer_tasks = 0;
297	  for (uint32_t i = 0U; i < static_cast<uint32_t>(num_tensors_); ++i) {
298	    state.prev_task = nullptr;
299	    state.prev_block_index = UINT64_MAX;
300	    for (size_t k = 0U; k < num_block_indices; ++k) {
301	      const bool is_last_block = (k == num_block_indices - 1);
302	      const auto block_index = block_indices[k];
303	      const auto cur_block_size = is_last_block ? tail_block_size : block_size;
304	      if (state.buffer_index != state.prev_buffer_index) {
305	        num_transfer_tasks = 0;
306	      }
307	      if (!AppendBlockTransferTask(ret, state, i, block_size, block_index, cur_block_size, max_block_size_)) {
308	        ++num_transfer_tasks;
309	      }
310	      ++state.buffer_block_index;
311	      if ((state.buffer_block_index >= buffer_block_num) || (num_transfer_tasks >= kBufferBlocks)) {
312	        buffer_block_nums_.emplace_back(state.buffer_block_index);
313	        used_buffer_indices.emplace(state.buffer_index);
314	        ret.emplace_back(TransferBlocksTask{kTaskTypeEndBlock, state.buffer_index, TransferBlockSpan{}});
315	        state.buffer_index = (state.buffer_index + 1) % num_buffers_;
316	        state.buffer_block_index = 0;
317	        state.prev_task = nullptr;
318	      }
319	      state.prev_block_index = block_index;
320	    }
321	  }
322	  FinalizeTransferTasks(ret, state.buffer_block_index, state.buffer_index, buffer_block_nums_);
323	  return ret;
324	}
325	
326	std::vector<TransferBlocksTask> DataTransferTaskGenerator::DoGenerateForClientBlocks(
327	    uint32_t block_size, uint32_t tail_block_size, uint32_t num_block_indices, const uint64_t *block_indices,
328	    const uint64_t *remote_block_indices) {
329	  std::vector<TransferBlocksTask> ret;
330	  const uint32_t buffer_block_num = buffer_size_ / block_size;
331	  std::set<uint32_t> used_buffer_indices;
332	  (void)DoGenerate(block_size, tail_block_size, num_block_indices, remote_block_indices);
333	  uint32_t buffer_task_index = 0U;
334	  // generate remote block num for every buffer
335	  auto remote_buffer_block_num = buffer_block_nums_[buffer_task_index];
336	  BlockTaskGenState state{};
337	  for (uint32_t i = 0U; i < static_cast<uint32_t>(num_tensors_); ++i) {
338	    state.prev_task = nullptr;
339	    state.prev_block_index = UINT64_MAX;
340	    for (size_t k = 0U; k < num_block_indices; ++k) {
341	      const bool is_last_block = (k == num_block_indices - 1);
342	      const auto block_index = block_indices[k];
343	      const auto cur_block_size = is_last_block ? tail_block_size : block_size;
344	      (void)AppendBlockTransferTask(ret, state, i, block_size, block_index, cur_block_size, max_block_size_);
345	      ++state.buffer_block_index;
346	      if ((state.buffer_block_index >= buffer_block_num) || (state.buffer_block_index >= remote_buffer_block_num)) {
347	        used_buffer_indices.emplace(state.buffer_index);
348	        ret.emplace_back(TransferBlocksTask{kTaskTypeEndBlock, state.buffer_index, TransferBlockSpan{}});
349	        buffer_task_index++;
350	        GetNextBufBlockNum(buffer_task_index, remote_buffer_block_num);
351	        state.buffer_index = (state.buffer_index + 1) % num_buffers_;
352	        state.buffer_block_index = 0;
353	        state.prev_task = nullptr;
354	      }
355	      state.prev_block_index = block_index;
356	    }
357	  }
358	  if ((!ret.empty()) && (ret.back().task_type != kTaskTypeEndBlock)) {
359	    ret.emplace_back(TransferBlocksTask{kTaskTypeEndBlock, state.buffer_index, TransferBlockSpan{}});
360	  }
361	  return ret;
362	}
