364	void DataTransferTaskGenerator::GetNextBufBlockNum(uint32_t buffer_task_index,
365	                                                   uint32_t &remote_buffer_block_num) const {
366	  if (buffer_task_index < buffer_block_nums_.size()) {
367	    remote_buffer_block_num = buffer_block_nums_[buffer_task_index];
368	  }
369	}
