371	std::vector<TransferBlocksTask> DataTransferTaskGenerator::DoGenerateForLargeBlock(
372	    uint32_t block_size, uint32_t num_block_indices, const uint64_t *block_indices) const {
373	  std::vector<TransferBlocksTask> ret;
374	  const uint32_t buffer_index = 0;
375	  for (uint32_t i = 0U; i < static_cast<uint32_t>(num_tensors_); ++i) {
376	    for (size_t k = 0U; k < num_block_indices; ++k) {
377	      AppendLargeBlockChunkTasks(ret, buffer_index, i, block_size, block_indices[k], buffer_size_);
378	    }
379	  }
380	  return ret;
381	}
382	
383	std::vector<TransferBlocksTask> DataTransferTaskGenerator::GenerateTasks(int64_t tensor_size, uint32_t block_size) {
384	  std::vector<TransferBlocksTask> ret;
385	  auto block_num = tensor_size / block_size;
386	  auto tail_block_size = tensor_size - block_size * block_num;
387	  if (tail_block_size > 0) {
388	    ++block_num;
389	  } else {
390	    tail_block_size = block_size;
391	  }
392	  std::vector<uint64_t> block_indices(block_num);
393	  std::iota(block_indices.begin(), block_indices.end(), 0U);
394	  return (block_size > buffer_size_)
395	             ? DoGenerateForLargeBlock(block_size, static_cast<uint32_t>(block_indices.size()), block_indices.data())
396	             : DoGenerate(static_cast<uint32_t>(block_size), static_cast<uint32_t>(tail_block_size),
397	                          static_cast<uint32_t>(block_indices.size()), block_indices.data());
398	}
399	
400	std::vector<TransferBlocksTask> DataTransferTaskGenerator::GenerateTasks(uint32_t block_size,
401	                                                                         uint32_t num_block_indices,
402	                                                                         const uint64_t *block_indices,
403	                                                                         const uint64_t *remote_block_indices) {
404	  LLMLOGD("GenerateTasks block_size:%u, buffer_size:%u", block_size, buffer_size_);
405	  if (block_size > buffer_size_) {
406	    return DoGenerateForLargeBlock(block_size, num_block_indices, block_indices);
407	  } else if (remote_block_indices == nullptr) {
408	    return DoGenerate(block_size, block_size, num_block_indices, block_indices);
409	  } else {
410	    return DoGenerateForClientBlocks(block_size, block_size, num_block_indices, block_indices, remote_block_indices);
411	  }
412	}
