437	ge::Status D2HDataTransferClient::Prepare(const CacheEntry &cache_entry, const CacheKey &cache_key,
438	                                          const PullCacheParam &pull_cache_param) {
439	  bool is_blocks_to_cont = (!pull_cache_param.prompt_blocks.empty()) && pull_cache_param.decoder_blocks.empty();
440	  LLM_CHK_BOOL_RET_STATUS((!is_blocks_to_cont), ge::LLM_PARAM_INVALID,
441	                          "Blocks to continuous memory is not supported by D2H data transfer");
442	  LLM_CHK_STATUS_RET(
443	      ValidateD2HClientPullLayout(num_buffers_, pull_cache_param.prompt_blocks.size(), validated_request_size_),
444	      "Invalid D2H pull request layout");
445	  buffer_size_ = kDefaultBufferSize;
446	  auto recv_flag_base = PtrToPtr<void, uint8_t>(comm_entity_->GetEntityInfo().local_req_ptr) +
447	                        sizeof(TransferCacheReq) +
448	                        sizeof(TransferInfo) * (num_buffers_ + pull_cache_param.prompt_blocks.size());
449	  for (uint32_t i = 0U; i < num_buffers_; ++i) {
450	    const size_t buffer_size = buffer_size_;
451	    auto buffer_data =
452	        comm_entity_->GetCacheManager()->GetNpuMemPool()->Alloc(buffer_size, static_cast<int32_t>(timeout_in_ms_));
453	    // 需要新的错误码
454	    LLM_CHK_BOOL_RET_STATUS(buffer_data != nullptr, ge::LLM_OUT_OF_MEMORY,
455	                            "Failed to allocate transfer buffer, size = %zu", buffer_size);
456	    buffers_.emplace_back(PtrToPtr<void, uint8_t>(buffer_data));
457	    auto recv_flag_ptr = PtrToPtr<uint8_t, int32_t>(recv_flag_base + i * sizeof(int32_t));
458	    *recv_flag_ptr = 0;
459	    recv_flags_.emplace_back(recv_flag_ptr);
460	  }
461	  auto send_flag =
462	      comm_entity_->GetCacheManager()->GetNpuMemPool()->Alloc(sizeof(int32_t), static_cast<int32_t>(timeout_in_ms_));
463	  LLM_CHK_BOOL_RET_STATUS(send_flag != nullptr, ge::LLM_OUT_OF_MEMORY, "Failed to allocate memory for sending flag.");
464	  send_dev_flag_ = PtrToPtr<void, uint8_t>(send_flag);
465	  auto host_flag = static_cast<uint8_t>(1U);
466	  LLM_CHK_ACL_RET(aclrtMemcpy(send_dev_flag_, sizeof(uint8_t), &host_flag, sizeof(uint8_t), ACL_MEMCPY_HOST_TO_DEVICE));
467	
468	  LLM_CHK_STATUS_RET(SendRequest(cache_entry, cache_key, pull_cache_param), "Failed to send request");
469	  // PUT req & flag
470	  LLMLOGD("request sent");
471	  const ResponseInfo *response_info = nullptr;
472	  LLM_CHK_STATUS_RET(comm_entity_->GetResponse(response_info, &timeout_tp_), "Failed to get response");
473	  const auto &response = *response_info;
474	  LLM_CHK_STATUS_RET(response.ret_code, "Failed to pull cache, server returned: %u", response.ret_code);
475	  LLMLOGD("response received, block_size = %u", response.block_size);
476	  for (uint32_t i = 0U; i < num_buffers_; ++i) {
477	    auto remote_flag_addr = ValueToPtr(response.sync_flag_addresses[i]);
478	    remote_receive_flag_addresses_.emplace_back(static_cast<uint8_t *>(remote_flag_addr));
479	  }
480	  LLM_CHK_STATUS_RET(GenerateTasks(cache_entry, pull_cache_param, response), "Failed to generate tasks");
481	  return ge::SUCCESS;
482	}
483	
484	ge::Status D2HDataTransferClient::GenerateTasks(const CacheEntry &cache_entry, const PullCacheParam &pull_cache_param,
485	                                                const ResponseInfo &response) {
486	  std::vector<std::shared_ptr<void>> cache_addrs;
487	  if (pull_cache_param.dst_tensor_indices.empty()) {
488	    cache_addrs = cache_entry.cache_addrs;
489	  } else {
490	    const uint64_t layer_start_tensor_index = pull_cache_param.dst_tensor_indices.front();
491	    cache_addrs.assign(
492	        cache_entry.cache_addrs.begin() + layer_start_tensor_index,
493	        cache_entry.cache_addrs.begin() + layer_start_tensor_index + pull_cache_param.dst_tensor_indices.size());
494	  }
495	  DataTransferTaskGenerator task_generator(cache_addrs.size(), buffers_.size(), buffer_size_);
496	  if (cache_entry.num_blocks == 0) {
497	    // to cont. tensor
498	    block_size_ = response.block_size;
499	    LLM_CHK_BOOL_RET_STATUS(block_size_ > 0, ge::FAILED, "block size from response is 0");
500	    const auto tensor_size =
501	        pull_cache_param.size > 0 ? pull_cache_param.size : static_cast<int64_t>(cache_entry.stride);
502	    tasks_ = task_generator.GenerateTasks(tensor_size, response.block_size);
503	    for (const auto &cache_addr : cache_addrs) {
504	      tensor_addresses_.emplace_back(PtrToPtr<void, uint8_t>(cache_addr.get()) +
505	                                     cache_entry.stride * pull_cache_param.batch_index);
506	    }
507	  } else {
508	    // to blocks
509	    block_size_ = cache_entry.stride;
510	    if (pull_cache_param.prompt_blocks.empty()) {
511	      std::vector<uint64_t> remote_block_indices(pull_cache_param.decoder_blocks.size());
512	      std::iota(remote_block_indices.begin(), remote_block_indices.end(), 0U);
513	      tasks_ = task_generator.GenerateTasks(block_size_, pull_cache_param.decoder_blocks.size(),
514	                                            pull_cache_param.decoder_blocks.data(), remote_block_indices.data());
515	    } else {
516	      tasks_ =
517	          task_generator.GenerateTasks(block_size_, pull_cache_param.decoder_blocks.size(),
518	                                       pull_cache_param.decoder_blocks.data(), pull_cache_param.prompt_blocks.data());
519	    }
520	    for (const auto &cache_addr : cache_addrs) {
521	      tensor_addresses_.emplace_back(PtrToPtr<void, uint8_t>(cache_addr.get()));
522	    }
523	  }
524	  return ge::SUCCESS;
525	}
526	
527	ge::Status D2HDataTransferClient::SendRequest(const CacheEntry &cache_entry, const CacheKey &cache_key,
528	                                              const PullCacheParam &pull_cache_param) const {
529	  auto fill_req_func = [this, &cache_entry, &cache_key, &pull_cache_param](TransferCacheReq &request,
530	                                                                           uint64_t &size) -> void {
531	    FillRequest(cache_entry, cache_key, pull_cache_param, request, size);
532	  };
533	  return comm_entity_->SendRequest(fill_req_func, stream_);
534	}
535	
536	void D2HDataTransferClient::FillRequest(const CacheEntry &cache_entry, const CacheKey &cache_key,
537	                                        const PullCacheParam &pull_cache_param, TransferCacheReq &request,
538	                                        uint64_t &size) const {
539	  size = validated_request_size_;
540	  request.req_size = size;
541	  request.is_pull_block = static_cast<uint32_t>(!pull_cache_param.prompt_blocks.empty());
542	  request.num_tensors = pull_cache_param.dst_tensor_indices.empty()
543	                            ? static_cast<uint32_t>(cache_entry.cache_addrs.size())
544	                            : static_cast<uint32_t>(pull_cache_param.dst_tensor_indices.size());
545	  request.cache_id = cache_key.prompt_cache_id;
546	  request.batch_index = cache_key.prompt_batch_index;
547	  request.req_id = cache_key.req_id;
548	  request.prefix_id = cache_key.prefix_id;
549	  request.model_id = cache_key.model_id;
550	  request.cache_id = cache_key.prompt_cache_id;
551	  request.dst_placement = 0;
552	  request.batch_index = cache_key.prompt_batch_index;
553	  request.block_size = cache_entry.num_blocks > 0 ? cache_entry.stride : 0;
554	  request.buffer_info_count = pull_cache_param.prompt_blocks.size();
555	  request.dst_addr_count = buffers_.size();
556	  request.dst_buffer_size = buffer_size_;
557	  request.timeout_in_ms = static_cast<int32_t>(timeout_in_ms_);
558	  request.src_tensor_indices_size = pull_cache_param.src_tensor_indices.size();
559	  request.src_tensor_start_index = 0U;
560	  if (!pull_cache_param.src_tensor_indices.empty()) {
561	    request.src_tensor_start_index = pull_cache_param.src_tensor_indices.front();
562	  }
563	  if (cache_entry.num_blocks == 0) {
564	    // local is cont.
565	    request.pull_size = pull_cache_param.size > 0 ? pull_cache_param.size : static_cast<int64_t>(cache_entry.stride);
566	  } else {
567	    request.pull_size =
568	        static_cast<int64_t>(pull_cache_param.decoder_blocks.size()) * static_cast<int64_t>(cache_entry.stride);
569	  }
570	  for (size_t i = 0U; i < buffers_.size(); ++i) {
571	    request.transfer_infos[i].dst_addr = buffers_[i];
572	  }
573	  auto *block_infos = &request.transfer_infos[request.dst_addr_count];
574	  uint64_t max_block_index = 0;
575	  for (size_t i = 0U; i < pull_cache_param.prompt_blocks.size(); ++i) {
576	    const auto remote_block_index = pull_cache_param.prompt_blocks[i];
577	    if (max_block_index < remote_block_index) {
578	      max_block_index = remote_block_index;
579	    }
580	    block_infos[i].buffer_info.block_start_index = remote_block_index;
581	    block_infos[i].buffer_info.buffer_len = request.block_size;
582	  }
583	  request.max_block_index = max_block_index;
584	}
585	
586	ge::Status D2HDataTransferClient::RunTasks() {
587	  LLMThreadPool thread_pool("ge_llm_copy", kCopyThreadNum);
588	  std::vector<std::future<ge::Status>> futures;
589	  std::chrono::steady_clock::time_point copy_start;
590	  for (const auto &task : tasks_) {
591	    if (task.task_type == kTaskTypeStartBlock) {
592	      LLM_CHK_BOOL_RET_STATUS(recv_flags_[task.buffer_index].Wait(&timeout_tp_) != 0, ge::LLM_TIMEOUT,
593	                              "Wait flag timed out, buffer_index:%u, timeout_ms:%ld", task.buffer_index,
594	                              timeout_in_ms_);
595	      LLMLOGD("wait flag success");
596	      copy_start = std::chrono::steady_clock::now();
597	    } else if (task.task_type == kTaskTypeTransferBlock) {
598	      auto fut = thread_pool.commit([this, &task]() -> ge::Status { return CopyAsync(task); });
599	      futures.emplace_back(std::move(fut));
600	    } else if (task.task_type == kTaskTypeEndBlock) {
601	      for (auto &fut : futures) {
602	        LLM_CHK_STATUS_RET(fut.get());
603	      }
604	      auto copy_end = std::chrono::steady_clock::now();
605	      auto cost = std::chrono::duration_cast<std::chrono::microseconds>(copy_end - copy_start).count();
606	      futures.clear();
607	      LLMLOGD("Buffer[%u] copy end, cost = %ld us", task.buffer_index, cost);
608	      // D2H flag
609	      LLM_CHK_STATUS_RET(buffered_sender_.Put(send_dev_flag_, remote_receive_flag_addresses_[task.buffer_index],
610	                                              sizeof(int32_t), true));
611	      LLMLOGD("Buffer[%u] flag sent", task.buffer_index);
612	    } else {
613	      // do nothing
614	    }
615	  }
616	  return ge::SUCCESS;
617	}
618	ge::Status D2HDataTransferClient::CopyAsync(const TransferBlocksTask &task) const {
619	  LLM_CHK_ACL_RET(aclrtSetCurrentContext(comm_entity_->GetCurrentContext()));
620	  auto src_addr = buffers_[task.buffer_index] + task.block_span.buffer_block_start * block_size_;
621	  auto dst_addr = tensor_addresses_[task.block_span.tensor_index] + task.block_span.tensor_offset;
622	  const auto size = task.block_span.size;
623	  LLMLOGD("Buffer[%u] copy, tensor_index:%u, src_offset = %lu, dst_offset = %lu, size = %u", task.buffer_index,
624	          task.block_span.tensor_index, task.block_span.buffer_block_start * block_size_, task.block_span.tensor_offset,
625	          size);
626	  LLM_CHK_ACL_RET(aclrtMemcpy(dst_addr, size, src_addr, size, ACL_MEMCPY_DEVICE_TO_HOST));
627	  return ge::SUCCESS;
628	}
629	}  // namespace llm
