66	ge::Status H2DDataTransferJob::Initialize(const CacheEntry &cache_entry, CommEntity &comm_entity, uint64_t offset) {
67	  const auto &request = comm_entity.GetRequest();
68	  const auto is_same_layout = ((cache_entry.num_blocks > 0) == (request.block_size > 0));
69	  LLM_CHK_BOOL_RET_STATUS(is_same_layout, ge::LLM_PARAM_INVALID,
70	                          "different layout is not supported by H2D data transfer, src_is_block = %d dst_is_block = %d",
71	                          static_cast<int32_t>(cache_entry.num_blocks > 0),
72	                          static_cast<int32_t>(request.block_size > 0));
73	  LLM_CHK_BOOL_RET_STATUS(comm_entity.GetCacheManager()->GetNpuMemPool() != nullptr, ge::LLM_PARAM_INVALID,
74	                          "Device memory pool is not enabled.");
75	  comm_entity_ = &comm_entity;
76	  src_task_generator_ = TaskBatcher(buffer_size_);
77	  dst_task_generator_ = TaskBatcher(buffer_size_);
78	  uint32_t block_size = cache_entry.stride;
79	  if (cache_entry.num_blocks == 0) {
80	    // cont.
81	    block_size = std::min(kDefaultBlockSize, static_cast<size_t>(request.pull_size));
82	  }
83	  const uint64_t num_tensors = (request.src_tensor_indices_size == 0U)
84	                                   ? cache_entry.cache_addrs.size()
85	                                   : static_cast<uint64_t>(request.src_tensor_indices_size);
86	  LLM_CHK_BOOL_RET_STATUS((num_tensors <= cache_entry.cache_addrs.size()), ge::LLM_PARAM_INVALID,
87	                          "src_tensor_indices_size[%u] is invalid, src_cache num is[%zu]",
88	                          request.src_tensor_indices_size, cache_entry.cache_addrs.size());
89	  src_task_generator_.Initialize(num_tensors, block_size, request.buffer_info_count,
90	                                 &request.transfer_infos[request.dst_addr_count]);
91	  dst_task_generator_.Initialize(num_tensors, block_size, request.buffer_info_count,
92	                                 &request.transfer_infos[request.dst_addr_count + request.buffer_info_count]);
93	  InitBufferContexts(cache_entry, request, comm_entity, offset);
94	  return ge::SUCCESS;
95	}
