97	void H2DDataTransferJob::InitBufferContexts(const CacheEntry &cache_entry, const TransferCacheReq &request,
98	                                            CommEntity &comm_entity, uint64_t offset) {
99	  std::vector<std::shared_ptr<void>> src_cache_addrs;
100	  if (request.src_tensor_indices_size == 0U) {
101	    src_cache_addrs = cache_entry.cache_addrs;
102	  } else {
103	    const size_t layer_start_tensor_index = static_cast<size_t>(request.src_tensor_start_index);
104	    const size_t layer_range_num_tensors = static_cast<size_t>(request.src_tensor_indices_size);
105	    src_cache_addrs.assign(cache_entry.cache_addrs.begin() + layer_start_tensor_index,
106	                           cache_entry.cache_addrs.begin() + layer_start_tensor_index + layer_range_num_tensors);
107	  }
108	  for (size_t i = 0U; i < kDefaultBufferNum; ++i) {
109	    BufferContext buffer_context{};
110	    buffer_context.buffer_index = i;
111	    buffer_context.offset = offset;
112	    buffer_context.stream = comm_entity.GetStream();
113	    buffer_context.comm_entity = &comm_entity;
114	    buffer_context.thread_pool = &thread_pool_;
115	    buffer_context.src_task_batcher = &src_task_generator_;
116	    buffer_context.dst_task_batcher = &dst_task_generator_;
117	    buffer_context.data_addresses = src_cache_addrs;
118	    buffer_context.request = &request;
119	    buffer_context.aclrt_context = comm_entity.GetCurrentContext();
120	    buffers_.emplace_back(std::move(buffer_context));
121	  }
122	}
