124	ge::Status H2DDataTransferJob::Process(bool &is_done) {
125	  size_t done_count = 0;
126	  for (auto &buffer_context : buffers_) {
127	    if (buffer_context.buffer == nullptr) {
128	      auto mem_pool = comm_entity_->GetCacheManager()->GetNpuMemPool();
129	      buffer_context.buffer = mem_pool->AllocShared(buffer_size_);
130	      LLMLOGD("Alloc npu buffer end.");
131	      if (buffer_context.buffer == nullptr) {
132	        LLMLOGW("Failed to allocate buffer memory, size = %zu, try next time", buffer_size_);
133	        continue;
134	      }
135	    }
136	
137	    bool state_changed = true;
138	    while (state_changed) {
139	      int prev_state = buffer_context.state;
140	      LLM_CHK_STATUS_RET(kBufferStates[buffer_context.state]->UpdateState(buffer_context));
141	      state_changed = (prev_state != buffer_context.state);
142	    }
143	    if (buffer_context.state == BufferStateEnd::kStateId) {
144	      ++done_count;
145	    }
146	  }
147	  is_done = (done_count == buffers_.size());
148	  if (is_done) {
149	    LLM_CHK_STATUS_RET(comm_entity_->SendResponse(ge::SUCCESS), "Failed to send response");
150	    LLMLOGD("Process done, send end flag");
151	  }
152	  return ge::SUCCESS;
153	}
