155	ge::Status BufferStateIdle::UpdateState(BufferContext &context) const {
156	  context.dst_buffer_slices = context.dst_task_batcher->NextBatch();
157	  if (context.dst_buffer_slices.empty()) {
158	    LLMLOGD("Buffer[%zu] changed to END state", context.buffer_index);
159	    context.state = BufferStateEnd::kStateId;
160	  } else {
161	    auto dst_transfer_info_num = context.dst_task_batcher->GetTransferInfoNum();
162	    context.buffer_slices = context.src_task_batcher->NextBatch(dst_transfer_info_num);
163	    LLMLOGD("Buffer[%zu] Next batch generated, num_tasks = %zu", context.buffer_index, context.buffer_slices.size());
164	    for (auto &task : context.buffer_slices) {
165	      LLMLOGD("buffer offset = %zu, data_index = %u, data_offset = %lu, data_size = %u", task.buffer_offset,
166	              task.data_index, task.data_offset, task.data_size);
167	    }
168	    LLMLOGD("Buffer[%zu] changed to COPY state", context.buffer_index);
169	    context.state = BufferStateCopy::kStateId;
170	  }
171	  return ge::SUCCESS;
172	}
173	
174	ge::Status BufferStateCopy::UpdateState(BufferContext &context) const {
175	  if (context.copy_futures.empty()) {
176	    context.batch_copy_start = std::chrono::steady_clock::now();
177	    const auto &tasks = context.buffer_slices;
178	    for (size_t i = 0; i < tasks.size(); ++i) {
179	      auto fut =
180	          context.thread_pool->commit([&context, i]() -> ge::Status { return BufferStateCopy::CopyAsync(context, i); });
181	      context.copy_futures.emplace_back(std::move(fut));
182	    }
183	  } else {
184	    bool need_wait = false;
185	    for (auto &fut : context.copy_futures) {
186	      if (fut.valid()) {
187	        if (fut.wait_for(std::chrono::microseconds(1)) == std::future_status::ready) {
188	          auto ret = fut.get();
189	          LLM_CHK_STATUS_RET(ret, "copy failed");
190	        } else {
191	          need_wait = true;
192	          break;
193	        }
194	      }
195	    }
196	    if (!need_wait) {
197	      auto tp_end = std::chrono::steady_clock::now();
198	      auto cost = std::chrono::duration_cast<std::chrono::microseconds>(tp_end - context.batch_copy_start).count();
199	      context.state = BufferStateTransfer::kStateId;
200	      LLMLOGD("Buffer[%zu] changed to TRANSFER state, copy_num = %zu, copy_size = %u, cost = %ld us.",
201	              context.buffer_index, context.buffer_slices.size(), context.buffer_slices.front().data_size, cost);
202	      context.copy_futures.clear();
203	    }
204	  }
205	  return ge::SUCCESS;
206	}
207	
208	ge::Status BufferStateCopy::CopyAsync(BufferContext &context, size_t slice_index) {
209	  LLM_CHK_ACL_RET(aclrtSetCurrentContext(context.aclrt_context));
210	  const auto &tasks = context.buffer_slices;
211	  auto &task = tasks[slice_index];
212	  auto src_addr =
213	      PtrToPtr<void, uint8_t>(context.data_addresses[task.data_index].get()) + task.data_offset + context.offset;
214	  auto dst_addr = PtrToPtr<void, uint8_t>(context.buffer.get()) + task.buffer_offset;
215	  LLM_CHK_ACL_RET(aclrtMemcpy(dst_addr, task.data_size, src_addr, task.data_size, ACL_MEMCPY_HOST_TO_DEVICE));
216	  LLMLOGD("Buffer[%zu] copy success, src_offset = %lu, dst_offset = %lu, size = %u", context.buffer_index,
217	          task.data_offset + context.offset, task.buffer_offset, task.data_size);
218	  return ge::SUCCESS;
219	}
220	
221	ge::Status BufferStateTransfer::UpdateState(BufferContext &context) const {
222	  if (context.event == nullptr) {
223	    // BatchPut
224	    LLM_CHK_STATUS_RET(BatchPutAsync(context));
225	    LLM_CHK_ACL_RET(aclrtCreateEvent(&context.event));
226	    LLM_CHK_ACL_RET(aclrtRecordEvent(context.event, context.stream));
227	  } else {
228	    aclrtEventRecordedStatus event_status{};
229	    LLM_CHK_ACL_RET(aclrtQueryEventStatus(context.event, &event_status));
230	    if (event_status != ACL_EVENT_RECORDED_STATUS_COMPLETE) {
231	      // 没有wait到，等待下一次, 不更新task index
232	      LLMLOGD("Buffer[%zu] transfer not ended", context.buffer_index);
233	    } else {
234	      aclrtDestroyEvent(context.event);
235	      context.event = nullptr;
236	      context.state = BufferStateIdle::kStateId;
237	      LLMLOGD("Buffer[%zu] changed to IDLE state", context.buffer_index);
238	    }
239	  }
240	  return ge::SUCCESS;
241	}
242	
243	ge::Status BufferStateTransfer::BatchPutAsync(BufferContext &context) {
244	  const auto buffer = PtrToPtr<void, uint8_t>(context.buffer.get());
245	  std::vector<HcclOneSideOpDesc> op_desc_batch;
246	  op_desc_batch.reserve(context.dst_buffer_slices.size());
247	  for (const auto &task : context.dst_buffer_slices) {
248	    const auto src_addr = buffer + task.buffer_offset;
249	    const auto dst_addr =
250	        PtrToPtr<void, uint8_t>(context.request->transfer_infos[task.data_index].dst_addr) + task.data_offset;
251	    op_desc_batch.emplace_back(HcclOneSideOpDesc{src_addr, dst_addr, task.data_size, HCCL_DATA_TYPE_UINT8});
252	    LLMLOGD("Buffer[%zu] [BatchPut] task added, src_offset = %u, dst_offset = %lu, size = %u", context.buffer_index,
253	            task.buffer_offset, task.data_offset, task.data_size);
254	  }
255	  LLM_CHK_STATUS_RET(context.comm_entity->BatchPutAsync(op_desc_batch), "Failed to batch put data");
256	  LLMLOGD("Buffer[%zu] BatchPutAsync success", context.buffer_index);
257	  return ge::SUCCESS;
258	}
259	}  // namespace llm
