120	ge::Status DataCacheEngine::Unregister(int64_t cache_id) {
121	  const auto start = std::chrono::steady_clock::now();
122	  std::lock_guard<std::mutex> lock(mu_);
123	  LLM_CHK_STATUS_RET(comm_mem_manager_->UnregisterCacheMem(cache_id), "Unregister cache addr failed, cache_id = %ld.",
124	                     cache_id);
125	  LLM_CHK_STATUS_RET(cache_manager_->UnregisterCacheEntry(cache_id), "Unregister cache entry failed, cache_id = %ld.",
126	                     cache_id);
127	  LLMLOGI("[cache_id:%ld][Unregister] success, cost = %ld ms", cache_id,
128	          std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - start).count());
129	  return ge::SUCCESS;
130	}
